from auto_config.generator.enb.managed_objects.managed_object import ManagedObject


class AntlParamsGenerator(ManagedObject):

    def _prepare_section_content(self, execution_config, *args, **kwargs):

        antPortId = self.get_antPortId()
        self.set_parameter('antPortId', antPortId)
        self.set_parameter('hdlcCommunicationAllowed', 'false')
        self.set_parameter('dcVoltage', self.get_dcVoltage(antPortId))

    def get_antPortId(self):
        configured_antennas = sum([
            int(radio_ent['antenna_count']) for radio_key, radio_ent in self.enb_ent_config['radios'].items()
            if (int(radio_key) < int(self.radio_num))
        ])

        return int(self.mo_num) - configured_antennas

    def get_dcVoltage(self, antPortId):
        return self.enb_ent_config['radios'][self.radio_num]['antennas']['dc_voltage'][antPortId - 1]
